<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');class PromotionsTest extends HRC_Controller{	public function __construct()	{		parent::__construct();		$this->products = modules::run('pages/Promotion/getProductsPromotions');	}	public function index()	{		$products = Product::whereHas('sizes', function($q){			$q->whereHas('price', function($q){				$q->promotion();			});		})->get();		$sizes = ProductSize::whereHas('price', function($q){			$q->promotion();		})->get();				foreach ($sizes as $key => $size) {			echo $key + 1;			echo "<h1>".$size->product->name."</h1>";		}	}	public function generate()	{	}}